function replayAccessEvents(events) {
  if (!Array.isArray(events)) throw new TypeError('events must be an array');
  let state = { pending: false, authenticated: false, principal: null, scope: null, error: null };
  const required = (value, name) => {
    if (typeof value !== 'string' || value.trim() === '') throw new TypeError(name + ' must be non-empty');
    return value.trim();
  };

  for (const event of events) {
    if (!event || typeof event !== 'object' || Array.isArray(event)) throw new TypeError('invalid event');
    switch (event.type) {
      case 'BEGIN':
        state = { ...state, pending: true, error: null };
        break;
      case 'ALLOW':
        state = {
          pending: false,
          authenticated: true,
          principal: required(event.principal, 'principal'),
          scope: required(event.scope, 'scope'),
          error: null
        };
        break;
      case 'DENY':
        state = {
          pending: false,
          authenticated: true,
          principal: null,
          scope: null,
          error: required(event.reason, 'reason')
        };
        break;
      case 'EXPIRE':
        state = { pending: false, authenticated: false, principal: null, scope: null, error: null };
        break;
      case 'CLEAR_ERROR':
        state = { ...state, error: null };
        break;
      default:
        throw new TypeError('unknown event type');
    }
  }
  return state;
}

module.exports = { replayAccessEvents };

