'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['replayAccessEvents']);
const { replayAccessEvents } = api;
const initial = { pending: false, authenticated: false, principal: null, scope: null, error: null };

const emptyA = replayAccessEvents([]);
const emptyB = replayAccessEvents([]);
assert.deepStrictEqual(emptyA, initial);
assert.notStrictEqual(emptyA, emptyB);

assert.deepStrictEqual(replayAccessEvents([{ type: 'BEGIN' }]), {
  pending: true, authenticated: false, principal: null, scope: null, error: null
});
assert.deepStrictEqual(replayAccessEvents([
  { type: 'BEGIN' },
  { type: 'ALLOW', principal: 'alice', scope: 'admin' }
]), {
  pending: false, authenticated: true, principal: 'alice', scope: 'admin', error: null
});
assert.deepStrictEqual(replayAccessEvents([
  { type: 'ALLOW', principal: 'alice', scope: 'read' },
  { type: 'DENY', reason: 'revoked' },
  { type: 'CLEAR_ERROR' }
]), {
  pending: false, authenticated: false, principal: null, scope: null, error: null
});
assert.deepStrictEqual(replayAccessEvents([
  { type: 'DENY', reason: 'bad token' },
  { type: 'BEGIN' }
]), {
  pending: true, authenticated: false, principal: null, scope: null, error: null
});
assert.deepStrictEqual(replayAccessEvents([
  { type: 'BEGIN' },
  { type: 'ALLOW', principal: 'bob', scope: 'write' },
  { type: 'EXPIRE' }
]), initial);

const events = [
  { type: 'ALLOW', principal: 'carol', scope: 'read' },
  { type: 'CLEAR_ERROR' }
];
const before = JSON.parse(JSON.stringify(events));
const result = replayAccessEvents(events);
assert.deepStrictEqual(events, before);
result.principal = 'changed';
assert.strictEqual(events[0].principal, 'carol');

for (const malformed of [
  null,
  {},
  [null],
  [{}],
  [{ type: 'UNKNOWN' }],
  [{ type: 'ALLOW', principal: '', scope: 'read' }],
  [{ type: 'ALLOW', principal: 'a', scope: '' }],
  [{ type: 'ALLOW', principal: 1, scope: 'read' }],
  [{ type: 'DENY', reason: '' }],
  [{ type: 'DENY', reason: 42 }]
]) assert.throws(() => replayAccessEvents(malformed), TypeError);

